CREATE TABLE q(k INT, v INT);
INSERT INTO q VALUES (2, 2), (2, 0);
WITH RECURSIVE c(k, v) AS (SELECT 0, 1 UNION ALL SELECT k + 1, v + k FROM c WHERE k < 3), d AS (SELECT k, v FROM c) SELECT a0.k, a1.k FROM q AS a0 CROSS JOIN (SELECT k, v FROM c WHERE k IS NOT NULL) AS a1 ON NOT ((SELECT count(*) FROM c AS s1 WHERE (SELECT max(s2.v) FROM d AS s2) = s1.v) = 0);
WITH RECURSIVE c(k, v) AS (SELECT 0, 1 UNION ALL SELECT k + 1, v + k FROM c WHERE k < 3), d AS (SELECT k, v FROM c) SELECT a0.k, a1.k FROM q AS a0 CROSS JOIN (SELECT k, v FROM c WHERE k IS NOT NULL) AS a1 WHERE NOT ((SELECT count(*) FROM c AS s1 WHERE (SELECT max(s2.v) FROM d AS s2) = s1.v) = 0);
WITH RECURSIVE c(k, v) AS (SELECT 0, 1 UNION ALL SELECT k + 1, v + k FROM c WHERE k < 3), d AS (SELECT k, v FROM c) SELECT a0.k, (SELECT count(*) FROM c AS s1 WHERE (SELECT max(s2.v) FROM d AS s2) = s1.v) FROM q AS a0 CROSS JOIN (SELECT k, v FROM c WHERE k IS NOT NULL) AS a1;
WITH RECURSIVE c(k, v) AS (SELECT 0, 1 UNION ALL SELECT k + 1, v + k FROM c WHERE k < 3), d AS (SELECT k, v FROM c) SELECT a0.k FROM q AS a0 WHERE (SELECT count(*) FROM c AS s1 WHERE (SELECT max(s2.v) FROM d AS s2) = s1.v) = 1;
WITH RECURSIVE c(k, v) AS (SELECT 0, 1 UNION ALL SELECT k + 1, v + k FROM c WHERE k < 3), d AS (SELECT k, v FROM c) SELECT a0.k FROM q AS a0, (SELECT k, v FROM c WHERE k IS NOT NULL) AS a1 WHERE (SELECT count(*) FROM d AS s1) = 4;
WITH RECURSIVE c(k, v) AS (SELECT 0, 1 UNION ALL SELECT k + 1, v + k FROM c WHERE k < 3), d AS (SELECT k, v FROM c) SELECT a0.k, a1.k FROM q AS a0 CROSS JOIN c AS a1 WHERE (SELECT count(*) FROM c AS s1 WHERE (SELECT max(s2.v) FROM d AS s2) = s1.v) = 1;
WITH c(k, v) AS MATERIALIZED (SELECT k, v FROM q), d AS (SELECT k, v FROM c) SELECT a0.k, a1.k FROM q AS a0 CROSS JOIN (SELECT k, v FROM c WHERE k IS NOT NULL) AS a1 WHERE NOT ((SELECT count(*) FROM c AS s1 WHERE (SELECT max(s2.v) FROM d AS s2) = s1.v) = 0);
WITH c(k, v) AS MATERIALIZED (SELECT k, v FROM q), d AS (SELECT k, v FROM c) SELECT a0.k, a1.k FROM q AS a0 CROSS JOIN (SELECT k, v FROM c WHERE k IS NOT NULL) AS a1 ON NOT ((SELECT count(*) FROM c AS s1 WHERE (SELECT max(s2.v) FROM d AS s2) = s1.v) = 0);
